select public.prepify_load_bank('Chemistry', 1, $j$[["A chemist is studying the metabolic reactions in a human cell. What is this branch of chemistry called?",["inorganic Chemistry","Biochemistry","Physical Chemistry","Analytical Chemistry"],"B",3,1,"463ab4d1666f"],["Organic chemistry is defined as the study of substances containing carbon, but which of these is usually excluded?",["Proteins","Carbohydrates","Synthetic Polymers","Carbonates and Bicarbonates"],"D",3,0,"143ccbe6a8c3"],["Which of these is a primary goal of chemistry?",["Only studying living things","Avoiding the use of technology","Ignoring the study of energy","Investigating the changes that materials undergo"],"D",3,0,"8eea81e1a73a"],["A scientist is looking at the chemical changes that occur in the human body. This falls under:",["Physical Chemistry","Organic Chemistry","Biochemistry","Analytical Chemistry"],"C",3,1,"32e098ce7d6e"],["If a substance contains carbon but is an oxide, it is typically classified under:",["Organic Chemistry","Inorganic Chemistry","Geochemistry","Nuclear Chemistry"],"B",3,1,"4465c786f8ce"],["Environmental Chemistry is closely linked to studying:",["How to create more hazardous waste","Toxic substances that pollute the environment","Only nuclear reactions","Physical laws of motion"],"B",3,0,"d948f757e20c"],["Chemistry helps us understand:",["Natural phenomena","How to avoid chemical changes","Only the study of math","How to ignore properties of matter"],"A",3,0,"c48c61baba6b"],["\"Green chemistry\" models processes that:",["Reduce the use of hazardous substances","Use hazardous substances","Increase pollution","Only focus on biochemistry"],"A",3,0,"be2e67fdce56"],["What does chemistry investigate regarding matter?",["Only its composition","Only its structure","Only its interactions with energy","Its composition, structure, properties, and interactions"],"D",3,0,"67c8a6076a7d"],["A pharmaceutical company is developing a new medicine to target a specific protein in the body. Which branch is most involved?",["Geochemistry","Medicinal Chemistry","Analytical Chemistry","Nuclear Chemistry"],"B",3,0,"ff065a04e5c9"],["A scientist discovers a new reaction in the laboratory. Turning that discovery into a useful product is mainly an example of:",["Technology using scientific knowledge","Science only","Engineering only","Technology only"],"A",3,1,"5d0908fcd631"],["Designing machinery for manufacturing detergents is mainly the work of:",["Astronomers","Scientists","Engineers","Biochemists"],"C",3,0,"508018a0311b"],["A company develops a stronger plastic for packaging materials. Which branch is most directly involved?",["Biochemistry","Polymer Chemistry","Geochemistry","Nuclear Chemistry"],"B",3,1,"e315475080ca"],["Why would a chemist use analytical instruments?",["To increase production only","To identify and measure substances","To study stars","To design bridges"],"B",3,1,"f5eb3e230b39"],["Which activity represents engineering rather than science?",["Studying atomic structure","Investigating bond formation","Designing a chemical manufacturing plant","Discovering a new chemical reaction"],"C",3,0,"3df6e46dacaf"],["A team of researchers is investigating how a new type of plastic waste interacts with seawater minerals over time. Which interdisciplinary field of chemistry would be most appropriate to categorize this study?",["Nuclear Chemistry","Geochemistry","Organic Chemistry","Analytical Chemistry"],"B",3,0,"7288438803ec"],["A researcher investigates why iron rusts in the presence of air and moisture. This activity represents:",["Science","Engineering","Marketing","Technology"],"A",3,0,"f7f396d438da"],["A student wants to determine whether a new fertilizer increases crop yield. Which factor should remain constant throughout the experiment?",["Type of fertilizer","Amount of crop produced","Soil type and water supply","Experimental conclusion"],"C",3,1,"dd0ef2fdc924"],["Which situation best shows science, technology, and engineering working together?",["Memorizing chemical formulas","Building a water filtration system","Reading a chemistry book","Naming laboratory apparatus"],"B",3,0,"8ebd920f13de"],["A chemist studying greenhouse gases and their effects on climate is working in:",["Organic Chemistry","Nuclear Chemistry","Astrochemistry","Environmental Chemistry"],"D",3,1,"d2a1b2f3b517"],["An engineer designing the structure of a solar power plant is mainly applying:",["Engineering principles","Nuclear reactions","Organic reactions","Scientific investigation"],"A",3,1,"8e463f8850bf"],["The relationship between atoms, bonds, and matter is primarily investigated in:",["Polymer Chemistry","Geochemistry","Industrial Chemistry","Physical Chemistry"],"D",3,0,"e8947f2d8165"],["Which branch of chemistry deals with instruments and methods for identifying substances?",["Geochemistry","Analytical Chemistry","Astrochemistry","Polymer Chemistry"],"B",3,0,"514e2e96cd45"],["When frying potatoes, a food technologist analyzes the oil to understand how it breaks down. How is this an example of chemistry in action?",["It utilizes engineering to change the taste of potatoes","It is an example of nuclear chemistry altering food","It proves that oil is an inorganic substance","It uses analytical methods to monitor the quality of organic molecules"],"D",3,0,"8db3d3ef7cc8"],["Which of these is an example of an inorganic compound?",["Salt (NaCl)","A Carbohydrate","Plastic bag","A protein"],"A",3,0,"cb6dd852baf3"],["If you are researching how greenhouse gases contribute to climate change, what is your primary field of study?",["Polymer Chemistry","Medicinal Chemistry","Nuclear Chemistry","Environmental Chemistry"],"D",3,0,"c64f3cffc3aa"],["Why do we study chemistry?",["To apply concepts to new substances and technologies","To stop using all technology","To only study carbon compounds","To avoid studying matter"],"A",3,0,"2d81e176265f"],["How does technology improve the work of a chemist in the pharmaceutical industry?",["By reducing the need for chemical Knowledge","By removing the need for scientists to conduct research","By automatically making every medicine safe","By allowing for the creation of completely new medicines using advanced analytical and identifying tools"],"D",3,1,"bfdfe00c89af"],["A student claims that chemistry is important only in laboratories. Which example best disproves this claim?",["Using a telescope","Cooking food at home","Reading a history book","Playing football"],"B",3,1,"5742cfc87aae"],["Which activity demonstrates the role of chemistry in agriculture?",["Producing fertilizers to improve crop yield","Designing road networks","Constructing buildings","Manufacturing furniture"],"A",3,0,"2f2e48319868"],["Which of these is a valid interpretation of the \"Nature of Science\" in Chemistry?",["Science is purely for building machines","Science provides the foundational understanding to explain phenomena, while technology applies this to solve problems","Chemistry is a stagnant field with no interdisciplinary potential","Engineering is the study of matter and energy changes"],"B",3,0,"ac24c0d3a301"],["Which of this best describes the \"Interdisciplinary\" nature of modern chemistry?",["It uses concepts from other fields like physics, biology, and environmental science","It refuses to use outside information","It only uses math","It is strictly limited to one textbook"],"A",3,0,"7b45365d6e55"],["Why is the study of 'matter's interactions' essential to modern medicine?",["It helps in avoiding all chemical changes","It is only concerned with identifying carbon","It is irrelevant to energy considerations","It helps in understanding how drugs bond with biological targets"],"D",3,0,"0d1b2786b578"],["Which branch would be most concerned with the toxicological pathways of heavy metal accumulation in organisms?",["Biochemistry","Organic Chemistry","Environmental Chemistry","Analytical Chemistry"],"C",3,0,"b250053290cc"],["Why would a scientist investigating the \"Middle Ages\" of chemical history need to distinguish between science and engineering?",["To prove engineering is older than science","To understand the evolution of how we explored nature versus how we built tools","To show that chemistry didn't exist in the past","It is not important"],"B",3,1,"add2967af34f"],["Why would a study on the effect of volcanic gases on Earth's atmosphere be categorized as Geochemistry?",["Because volcanoes are only organic","Because it doesn't involve energy","Because it involves Earth materials and their chemical transformations","Because it uses only hand tools"],"C",3,0,"057235b16582"],["A student concludes that a fertilizer is effective after testing it on only one plant. What is the major weakness in this conclusion?",["Lack of observation","Insufficient evidence","Incorrect measurements","Excessive experimentation"],"B",3,1,"958a99a52240"],["If a substance is used as a medicine, which sub-fields of chemistry are likely to have collaborated on its development?",["Inorganic Chemistry and Engineering","Physical Chemistry","Organic Chemistry and Biochemistry","Only Analytical Chemistry"],"C",3,1,"9deb52b68b6a"],["Which branch of chemistry provides the \"tools\" to verify that a manufacturer is not putting toxic chemicals in drinking water?",["Analytical Chemistry","Organic Chemistry","Inorganic Chemistry","Physical Chemistry"],"A",3,0,"381a651be6d4"],["A scientist records all observations, including unexpected ones. This practice mainly helps to:",["Eliminate experimentation","Increase objectivity","Reduce accuracy","Save time"],"B",3,1,"ecb5343396f4"],["Why are scientific conclusions often considered tentative?",["Scientists lack confidence","Experiments are unnecessary","Observations are always incorrect","New evidence can refine existing knowledge"],"D",3,0,"1c3a69fefb76"],["A chemist studies the effect of temperature on reaction rates. The primary objective is to understand:",["Composition of matter","Chemical behavior of matter","Origin of the universe","Manufacturing processes"],"B",3,1,"c6f80fdd41c1"],["Which characteristic distinguishes science from personal opinion?",["Evidence-based reasoning","Imagination","Creativity","Observation alone"],"A",3,0,"3132803ec152"],["A researcher finds that repeated experiments produce conflicting results. The most appropriate action is to:",["Ignore the unusual results","Reevaluate the procedure and collect more data","Publish the first result obtained","Select the result that supports the hypothesis"],"B",3,0,"6abf335367fc"],["Which branch would be least involved in investigating the composition of a newly discovered meteorite?",["Astrochemistry","Analytical Chemistry","Geochemistry","Medicinal Chemistry"],"D",3,0,"17132357d1a4"],["A chemist develops a new drug, an engineer designs a machine to manufacture it, and a company produces it on a large scale. Which sequence correctly represents the process?",["Technology → Science → Engineering","Science → Engineering → Technology","Engineering → Technology → Science","Technology → Engineering → Science"],"B",3,1,"f12b0bd2a016"],["Which branch of chemistry would be most useful for a geologist analyzing the composition of ores?",["Geochemistry","Biochemistry","Organic Chemistry","Theoretical Chemistry"],"A",3,0,"a1e9e20f8c0e"],["Which situation best demonstrates that chemistry contributes to the quality of human life?",["Discovery of a distant galaxy","Development of water purification techniques","Mapping ocean currents","Measuring earthquake intensity"],"B",3,0,"343ef78588b4"],["Which branch of chemistry would most likely cooperate with environmental scientists to monitor toxic substances in a river?",["Astrochemistry","Polymer Chemistry","Industrial Chemistry","Analytical Chemistry"],"D",3,0,"423f3f24df1f"],["A chemical process works well in the laboratory but fails during large-scale production. The problem is most likely addressed by:",["Historians","Chemical Engineers","Geologists","Astronomers"],"B",3,0,"2c4b02d14387"],["Why is it important for scientific experiments to be reproducible?",["To verify the reliability of results","To reduce the need for observations","To eliminate hypotheses","To increase the cost of research"],"A",3,0,"f585ee54702d"],["A scientist studies the chemicals present in ancient fossils to understand past life on Earth. This investigation combines chemistry with:",["Literature and Art","Astronomy and Music","Archaeology and Biology","Economics and Commerce"],"C",3,1,"c5bd3b36d856"],["A researcher investigating a disease first identifies the chemicals involved and then develops a treatment. This sequence shows that:",["Discoveries occur without research","Technology always comes before science","Engineering replaces chemistry","Application often follows scientific understanding"],"D",3,0,"ab9eebd1d251"],["Which characteristic of science allows knowledge to improve over time?",["Refusal to accept new ideas","Dependence on authority","Continuous testing and evaluation of evidence","Memorization of facts"],"C",3,0,"3ff0126ad594"],["A team of scientists from different fields works together to solve a water contamination problem. This approach highlights:",["The importance of interdisciplinary collaboration","The independence of scientific disciplines","The replacement of science by technology","The limitations of chemistry"],"A",3,0,"a3e1aa28660f"],["The discovery of synthetic fertilizers has significantly increased food production. This example best illustrates the impact of chemistry on:",["Astronomy","Agriculture","Literature","Transportation"],"B",3,0,"5b53e83636d9"],["A scientist proposes an explanation for a phenomenon. Before it can be widely accepted, it must:",["Be memorized by students","Be approved by engineers","Be tested repeatedly","Be printed in textbooks"],"C",3,1,"99e2df45e6ee"],["A chemist measures how air pollutants from factories affect rainwater. This work belongs to:",["Organic Chemistry","Nuclear Chemistry","Astrochemistry","Environmental Chemistry"],"D",3,1,"d2a1b2f3b517"],["A medicine that works in a small lab trial must now be made in tonnes in a factory. Which experts mainly solve this scale-up problem?",["Historians","Chemical engineers","Geologists","Astronomers"],"B",3,1,"2c4b02d14387"],["Studying how enzymes break down food inside the stomach is part of:",["Physical Chemistry","Inorganic Chemistry","Biochemistry","Analytical Chemistry"],"C",3,1,"32e098ce7d6e"],["A scientist examines rocks and minerals to find which elements they contain. This branch is:",["Geochemistry","Biochemistry","Polymer Chemistry","Theoretical Chemistry"],"A",3,0,"a1e9e20f8c0e"],["A laboratory tests a water sample to find exactly which metals are present and in what amounts. This is:",["Analytical Chemistry","Astrochemistry","Organic Chemistry","Geochemistry"],"A",3,1,"514e2e96cd45"],["Before a new scientific idea is accepted, other scientists must:",["memorise it","test it repeatedly and get the same results","publish it in a newspaper","vote on it"],"B",3,0,"99e2df45e6ee"],["Modern chemistry uses ideas from physics, biology and environmental science. This shows that chemistry is:",["interdisciplinary","outdated","limited to laboratories","only about metals"],"A",3,0,"7b45365d6e55"],["Studying the chemicals in meteorites and distant stars is called:",["Astrochemistry","Biochemistry","Geochemistry","Food Chemistry"],"A",3,0,"514e2e96cd45"]]$j$::jsonb, true);
select public.prepify_load_bank('Chemistry', 2, $j$[["Which state of matter is most likely to be found in stars due to extremely high temperatures?",["Solid","Plasma","Liquid","Bose-Einstein Condensate"],"B",3,0,"2a05a3c160d7"],["Which state of matter would have the highest fluidity?",["Plasma","Gas","Solid","Liquid"],"B",3,0,"b1c8cf9a2c30"],["Which of these is a pure substance composed of only one type of atom?",["Water","Air","Gold","Brass"],"C",3,0,"92d5f75c05c1"],["In which of the following is the arrangement of particles the least ordered?",["Diamond","Liquid water","Oxygen gas","Graphite"],"C",3,0,"345d99898525"],["Which mixture type shows the Tyndall effect, but its particles do not settle when kept stationary?",["Solution","Suspension","Colloid","Element"],"C",3,0,"409aa573d2ef"],["The conversion of liquid water into steam is an example of:",["Physical change","Decomposition","Nuclear change","Chemical change"],"A",3,0,"1bdf12c72f9b"],["Which sample is most likely to have the highest density under normal conditions?",["Oxygen gas","Water vapor","Ice cube","Iron nail"],"D",3,0,"b9d82fcce497"],["If you mix sugar in water and it disappears, the resulting mixture is best described as:",["A heterogeneous suspension","A homogeneous solution","A colloid","A pure compound"],"B",3,0,"208af0d9219b"],["What is the key difference between a colloid and a suspension?",["Colloids are homogeneous; suspensions are heterogeneous","Colloid particles are smaller and do not settle, unlike suspension particles","Suspensions are smaller than colloids","There is no difference"],"B",3,0,"4562a0a54ac3"],["Why are diamond and graphite considered allotropes of carbon?",["They contain different elements.","They have different atomic numbers.","They are different structural forms of the same element.","They have different chemical compositions."],"C",3,0,"dad87ab81f53"],["The ability of a liquid to flow is directly related to its:",["Compressibility","Fluidity","Density","Hardness"],"B",3,0,"52bd2157c36e"],["Which change is most likely to increase the solubility of many solid solutes in water?",["Lowering temperature","Stirring only","Removing solvent","Increasing temperature"],"D",3,0,"4f6fa5284e89"],["The dissolved and undissolved solute in a saturated solution are in:",["Chemical reaction","Nuclear equilibrium","Dynamic equilibrium","Thermal decomposition"],"C",3,0,"63d4dfe0f0a3"],["Which substance can be separated into its components by physical means?",["Pure Gold","Sucrose","Carbon Dioxide","A mixture of salt and sand"],"D",3,0,"1af984e5438b"],["What is the result when a saturated solution is cooled down?",["It becomes unsaturated","It may form crystals as the solubility decreases","It turns into a gas","The mass of the solvent increases"],"B",3,0,"226c4e248113"],["Why does gas exert pressure on the walls of its container?",["Because of the continuous random motion and collisions of particles","Because the particles are stationary","Because the container is heated","Because gas particles attract each other strongly"],"A",3,0,"09a7088b46db"],["What is most likely observed when extra solute is added to a saturated solution?",["Solvent disappears","The solution becomes a gas","Solute remains undissolved","All solute dissolves instantly"],"C",3,0,"67034f6ba926"],["Which factor has the greatest effect on whether a solution becomes saturated?",["Amount of solute and temperature","Color of solvent","Shape of container","Density of air"],"A",3,0,"b32255e779ef"],["In soft drinks, the substance present in the greatest amount is generally:",["Sugar","Carbon dioxide","Water","Salt"],"C",3,0,"8fca0ed94970"],["Compared with diamond, graphite:",["Has no carbon atoms","Is harder","Has a higher melting point","Conducts electricity better"],"D",3,0,"d1356997af2c"],["Which property makes diamond suitable for use as a cutting tool?",["Electrical conductivity","Soft structure","Solubility in water","Extreme hardness"],"D",3,0,"95adaeb21d35"],["An example of a liquid-in-gas colloid is:",["Fog","Smoke","Jelly","Milk"],"A",3,0,"a3bbbf6e9101"],["A scientist wants to separate mud from water. This is an example of separating a:",["True solution","Suspension","Colloid","Compound"],"B",3,1,"934630e027ce"],["Why is a suspension considered a heterogeneous mixture?",["Because its components are chemically bonded","Because its components are not uniformly distributed and can be separated","Because it is invisible to the naked eye","Because it is a pure substance"],"B",3,0,"7565e80de703"],["Which property of liquids allows them to take the shape of their container?",["High density","Fluidity","Compressibility","Rigid structure"],"B",3,0,"ab5ff84f326b"],["A liquid changes into a gas when:",["Particle motion decreases","Chemical bonds are permanently broken","New substances are formed","Particles gain sufficient energy to escape"],"D",3,0,"fb762c1f7bfa"],["If the intermolecular forces in a substance are significantly weakened without changing the chemical composition, which phase transition is most likely occurring at a macroscopic level?",["Deposition","Melting or Vaporization","Condensation","Sublimation to Plasma"],"B",3,0,"417eb6b57467"],["A student has four samples: oxygen, distilled water, brass, and sodium chloride. How many of these are pure substances?",["1","2","3","4"],"C",3,1,"457a1e2f2e5c"],["A beaker contains a saturated solution of potassium nitrate at 40°C with some undissolved crystals at the bottom. Which statement must be true?",["Dissolving has completely stopped.","Crystallization occurs faster than dissolving.","No more solute can ever dissolve.","Dissolving and crystallization occur at equal rates"],"D",3,0,"2f63add9e421"],["In an allotropic study, how does the hybridization of carbon in Diamond fundamentally dictate its physical hardness compared to Graphite?",["Diamond is heavier","Diamond's sp³ network creates a rigid 3D structure, whereas Graphite's sp² layers slide","Graphite has no carbon atoms","Diamond is a mixture, not an allotrope"],"B",3,0,"c40b300a677c"],["When a saturated solution is prepared at 80oC and then rapidly cooled to 20oC without agitation, it may become 'supersaturated.' Why is this state thermodynamically unstable?",["The solute concentration exceeds the equilibrium solubility limit for 20oC","The solvent evaporates","The molecules stop moving","The pressure increases"],"A",3,0,"f178b15866dd"],["In the context of the kinetic molecular theory, why do liquids exhibit fluidity?",["Their particles have zero kinetic energy","Their intermolecular forces are strong enough to hold volume, but weak enough to allow particle slippage","They are made of plasma","They have no mass"],"B",3,0,"827c29660e04"],["Graphite conducts electricity, while diamond does not, even though both consist entirely of carbon atoms. This difference is primarily due to:",["Difference in purity","Difference in atomic mass","Difference in the number of carbon atoms","Difference in atomic arrangement and bonding"],"D",3,0,"480713cd962e"],["A gas occupies 500 cm³ in a container. If transferred to a 1000 cm³ container at the same temperature, the gas will:",["Occupy 1000 cm³","Occupy 500 cm³ only","Remain at the bottom of the container","Become a liquid"],"A",3,0,"5f817d2fdd92"],["A chemist claims that a sample is an element because it cannot be separated by chemical means. Why is this reasoning incomplete?",["Some compounds also cannot be separated chemically.","Elements have fixed compositions.","The sample might be a mixture.","The inability to separate chemically does not alone prove it contains only one type of atom."],"D",3,1,"6686e35dbee4"],["If all intermolecular forces in a solid were suddenly reduced to nearly zero, the solid would most likely:",["Remain unchanged","Become more rigid","Behave like a gas","Become an element"],"C",3,0,"8025be33937e"],["Which of the following correctly describes the relationship between particle size and the Tyndall effect?",["Particles must be smaller than the wavelength of light","Particles must be of a size that effectively scatters light (1-1000 nm)","Particles must be larger than 1000 nm","Particle size has no effect"],"B",3,0,"87f0a9905a14"],["In a suspension, the term \"stationary\" refers to:",["The mixture is being heated","The state where the mixture is left undisturbed, allowing gravity to act on particles","The state where light is blocked","The state where the mixture is moving rapidly"],"B",3,0,"da446acbeaea"],["When analyzing the internal structure of matter, what does the term 'intermolecular spacing' explain about compressibility?",["Large spacing allows particles to be pushed closer together","Small spacing prevents compression","Spacing has no relation to compressibility","Large spacing makes compression impossible"],"A",3,0,"cdb41950dec0"],["When a solute is added to a solvent, why does the freezing point of the resulting solution often decrease?",["Because the solution gets hotter","Because the solvent becomes a gas","Because the solute is a metal","Because the solute disrupts the crystal lattice formation of the solvent"],"D",3,0,"88b5b8ce6ef6"],["Why is the formation of a compound considered a chemical change, while the formation of a mixture is a physical change?",["Compounds have fixed mass ratios; mixtures have variable ratios","Mixtures are always solids","Compounds are always liquids","There is no difference"],"A",3,0,"2cf67ecf6dc4"],["Two colorless liquids are placed in separate beakers. One is pure water, and the other is a salt solution. Which property would most reliably distinguish them?",["Color","Composition","State","Transparency"],"B",3,0,"73dbc475098c"],["Which process involves the greatest increase in particle freedom?",["Steam → Water","Water → Ice","Water → Steam","Ice → Water"],"C",3,0,"ca40f6849085"],["A mixture of iron filings and sulfur appears uniform after thorough mixing. Why is it still considered a mixture?",["It contains two elements not chemically combined.","It has a fixed composition.","New properties have developed.","It cannot be separated physically."],"A",3,0,"1c832c3baa03"],["A gas occupies a container of 2 L. If transferred to a 5 L container at the same temperature, the gas will:",["Increase its mass.","Become a liquid.","Expand to fill the 5 L container.","Occupy exactly 2 L."],"C",3,0,"542b0eda4213"],["If a solid carbon allotrope contains C₆₀ molecules arranged in a specific geometry, it is identified as:",["Diamond","Fullerene","Coal","Graphite"],"B",3,1,"12390239f056"],["A student claims that because air is invisible, it is not matter. Which observation most directly disproves this claim?",["Air is transparent.","Air contains oxygen.","Air is colorless.","Air can be compressed."],"D",3,1,"20872f815397"],["Why are Bose-Einstein Condensates (BEC) considered an \"exotic\" state of matter?",["They are found in volcanoes","They occur only at temperatures near absolute zero, where quantum effects become macroscopic","They are used to make steel","They are a form of smoke"],"B",3,0,"b6efe48f8ded"],["Which statement would be FALSE for every saturated solution at a given temperature?",["It contains dissolved solute.","Additional solute can dissolve without changing conditions.","Dissolving and crystallization may occur simultaneously.","Its concentration has reached a maximum value under those conditions."],"B",3,0,"3e57d7961dbf"],["Which of the following mixtures exhibits particles that can be separated by dialysis but not by filter paper?",["Suspension","Colloid","True Solution","Compound"],"B",3,0,"52d63e8641ca"],["Why do amorphous solids lack a definite melting point compared to crystalline solids?",["Because they have stronger intermolecular forces","Because they are actually liquids","Because they have higher density","Because they lack a long-range ordered internal structure"],"D",3,0,"6005f2000227"],["The density of a gas is inversely proportional to its volume at constant pressure. This physical behavior is rooted in:",["The compressibility of the gas due to vast intermolecular spaces","The chemical bonding between atoms","The high fluidity of the gas","The plasma state"],"A",3,0,"de580a030b6f"],["Which of the following correctly describes the relationship between particle size and the Tyndall effect?",["Particles must be smaller than the wavelength of light","Particles must be of a size that effectively scatters light","Particles must be larger than 1000 nm","Particle size has no effect"],"B",3,0,"78313328aa2e"],["Chalk powder stirred into water settles at the bottom after some time. This mixture is a:",["true solution","suspension","colloid","compound"],"B",1,1,"934630e027ce"],["In which state are the particles most widely spaced and least ordered?",["Ice","Liquid water","Steam","Iron"],"C",1,0,"345d99898525"],["A torch beam becomes visible when it passes through fog, but not through salt water. Fog is therefore a:",["true solution","colloid","compound","pure element"],"B",3,1,"78313328aa2e"],["Unlike diamond, graphite is used in electrodes because it:",["is harder","conducts electricity","has no carbon","is transparent"],"B",3,0,"d1356997af2c"],["A balloon becomes firm when air is blown into it. This shows that the air particles:",["are stationary","collide continuously with the walls and exert pressure","have no mass","turn into liquid"],"B",3,1,"09a7088b46db"],["A pumped-up football is heavier than a flat one. This observation shows that air:",["has mass and is matter","is invisible","is a colour","is not matter"],"A",3,1,"20872f815397"],["In a saturated solution at a fixed temperature, adding more solute:",["makes it dissolve completely","leaves the extra solute undissolved","turns the solution into a gas","removes the solvent"],"B",3,0,"3e57d7961dbf"],["Liquids can flow and take the shape of their container because their particles:",["are held in fixed positions","can slide past each other while staying close","have no forces between them","do not move"],"B",3,0,"827c29660e04"],["25 g of sugar is dissolved in 75 g of water. The concentration of the solution by mass is:",["75%","12.5%","33.3%","25%"],"D",3,1,"gen-chemistry-c2-mass-percent"],["5 g of urea is dissolved in 95 g of water. The concentration of the solution by mass is:",["5%","2.5%","95%","5.3%"],"A",3,1,"gen-chemistry-c2-mass-percent"],["25 g of urea is dissolved in 75 g of water. The concentration of the solution by mass is:",["33.3%","75%","12.5%","25%"],"D",3,1,"gen-chemistry-c2-mass-percent"],["20 g of urea is dissolved in 30 g of water. The concentration of the solution by mass is:",["66.7%","60%","40%","20%"],"C",3,1,"gen-chemistry-c2-mass-percent"],["5 g of copper sulphate is dissolved in 245 g of water. The concentration of the solution by mass is:",["2%","1%","5%","98%"],"A",3,1,"gen-chemistry-c2-mass-percent"],["10 g of urea is dissolved in 90 g of water. The concentration of the solution by mass is:",["5%","10%","11.1%","90%"],"B",3,1,"gen-chemistry-c2-mass-percent"]]$j$::jsonb, true);
